/**
 * Reset the workspace chrome back to the context-gathering view.
 *
 * On reload the page is server-rendered in planning mode (is-planning +
 * in-place skeletons) so the static chrome shows immediately. If there is
 * nothing to resume, fall back to the context form. Only relevant when
 * resumeSessionId is actually set — an ordinary load (free or template
 * mode, no ?sessionid=) never runs any of this, so it can't clobber
 * whatever #contextView/#templateModeView the server already rendered.
 *
 * @param {Object} elements
 */
const revertToContextView = (elements) => {
    const workspace = document.getElementById('courseaiWorkspace');
    if (workspace) {
        workspace.classList.remove('is-planning');
    }
    const planningView = document.getElementById('planningView');
    if (planningView) {
        planningView.style.display = 'none';
    }
    const compactChat = document.getElementById('compactChatCard');
    if (compactChat) {
        compactChat.style.display = 'none';
    }
    if (elements.contextView) {
        elements.contextView.style.display = '';
    }
};

/**
 * Resume the workspace from a snapshot when one is pending, falling back
 * to the context view when there is nothing to resume or resuming fails.
 *
 * @param {string} resumeSessionId
 * @param {Function} resumeFromSnapshot
 * @param {Object} elements
 * @param {Function} setResumeBootLoading
 * @returns {Promise<boolean>} True when the page was rebuilt from a snapshot.
 */
const attemptResume = async(resumeSessionId, resumeFromSnapshot, elements, setResumeBootLoading) => {
    let resumed = false;
    try {
        if (resumeSessionId) {
            resumed = await resumeFromSnapshot();
            if (!resumed) {
                revertToContextView(elements);
            }
        }
    } catch (resumeError) {
        revertToContextView(elements);
    } finally {
        // A resumed page decides about its own skeletons: a run that has not drawn its first
        // section keeps them, as the live stream does.
        if (!resumed) {
            setResumeBootLoading(false);
        }
    }
    return resumed;
};

/**
 * Initialize the courseai page.
 *
 * @param {Object} params
 */
export const init = async(params) => {
    try {
        const {guidelines, languages, defaultLang, coursetemplates} = parseCourseaiData(params);
        const state = createInitialState({defaultLang, guidelines, languages});
        state.templates = coursetemplates || [];
        state.selectedTemplateId = null;

        // Wire template mode switching before awaiting anything below: it
        // only needs `state`, not translated strings, and the Free/Template
        // buttons are clickable the instant the page renders — the
        // `await loadCourseaiStrings()` network round-trip used to leave
        // them dead until it resolved (a dynamic import() here made it
        // worse still, adding a second network wait on top).
        // The page's actions do not exist yet; the template's finish step
        // reads them from here once the generation is over.
        const templateHost = {actions: null};
        wireTemplateMode(state, templateHost);

        const texts = await loadCourseaiStrings();
        const elements = getCourseaiElements();

        // Decision log (§4) — instantiate before any module that needs it.
        const {emitLog, clearLog} = makeEmitLog(state);

        let markedParser = markedModule.marked;
        if (markedModule.parse) {
            markedParser = markedModule;
        }
        const activityLabels = getActivityLabels(texts);
        const generateButtonHtml = getGenerateButtonHtml(texts);

        const contextUi = createContextUi({
            state,
            languages,
            defaultLang,
            elements,
            Notification,
            CourseaiRepository,
            YUI,
            texts,
        });

        const stepsUi = createStepsUi({
            state,
            elements,
            generateButtonHtml,
            texts,
            clearLog,
        });

        const runPlanAction = createRunPlanAction({
            state,
            texts,
            sendPlanningFeedback,
            openSSEStream: (url, retry, mode, keepPlan) =>
                streamManager.openSSEStream(url, retry, mode, keepPlan),
        });

        const detailedUi = createDetailedUi({
            state,
            elements,
            activityLabels,
            getActivityIconUrl,
            escapeHtml,
            switchPlanMode: stepsUi.switchPlanMode,
            setProgress: stepsUi.setProgress,
            texts,
            formatTemplate,
            runPlanAction,
            emitLog,
        });

        const proposalsUi = createProposalsUi({
            state,
            texts,
            formatTemplate,
            runPlanAction,
            emitLog,
            detailedUi,
        });

        const planningUi = createPlanningUi({
            state,
            elements,
            activityLabels,
            getActivityIconUrl,
            escapeHtml,
            setProgress: stepsUi.setProgress,
            updateDetailedHeaderStats: detailedUi.updateDetailedHeaderStats,
            texts,
            formatTemplate,
        });

        const renderPlanMarkdown = makeRenderPlanMarkdown({markedParser, state, elements});

        let actions = null;
        const streamLifecycle = {};
        const createCourseFromSession = makeCreateCourseCallback({
            elements,
            stepsUi,
            texts,
            getActions: () => actions,
        });

        const streamManager = createStreamManager({
            state,
            elements,
            stepsUi,
            planningUi,
            detailedUi,
            proposalsUi,
            renderPlanMarkdown,
            emitLog,
            createCourseFromSession,
            texts,
            onStreamStart: () => streamLifecycle.onStreamStart && streamLifecycle.onStreamStart(),
            onStreamEnd: () => streamLifecycle.onStreamEnd && streamLifecycle.onStreamEnd(),
        });

        stepsUi.bindCloseStream(streamManager.closeStream);

        actions = createCourseaiActions({
            state,
            elements,
            Notification,
            CourseaiRepository,
            sendPlanningFeedback,
            createCourse,
            getCourseSettings,
            updateGenerateButton: contextUi.updateGenerateButton,
            refreshChipsRow: contextUi.refreshChipsRow,
            refreshGuidelineChip: contextUi.refreshGuidelineChip,
            stepsUi,
            planningUi,
            streamManager,
            texts,
            formatTemplate,
            emitLog,
        });

        templateHost.actions = actions;
        actions.bindEvents();

        const executionControls = createExecutionControls({state, elements, streamManager, texts, emitLog});
        executionControls.bindEvents();
        streamLifecycle.onStreamStart = executionControls.showStop;
        streamLifecycle.onStreamEnd = executionControls.hideControls;

        const {
            getResumeSessionId,
            setResumeBootLoading,
            setPlanningStreamVisible,
            parseJsonField,
            applyCourseTitleToHeader,
            buildCourseUrlFromResume,
            normalizeSnapshotStatus,
        } = makeResumeHelpers({state, elements, texts, params});

        const {
            buildSectionsFromDetailedPlan,
        } = makeChecklistHelpers({state, elements, texts});

        const hydrateDetailedPlanFromSnapshot = makeHydratePlan(detailedUi);
        const resumeSessionId = getResumeSessionId();

        // The service thread is the source of truth for the transcript on reload.
        // resume-snapshot falls back to its own rebuild for sessions started
        // before the thread was recorded, which carry none.
        const {replayThread} = makeThreadReplay({
            state,
            emitLog,
            localizeMessage,
            renderProposals: proposalsUi.renderProposals,
            texts,
        });

        const resumeFromSnapshot = makeResumeFromSnapshot({
            state,
            elements,
            CourseaiRepository,
            stepsUi,
            planningUi,
            detailedUi,
            proposalsUi,
            streamManager,
            actions,
            createCourseFromSession,
            parseJsonField,
            normalizeSnapshotStatus,
            buildSectionsFromDetailedPlan,
            buildCourseUrlFromResume,
            applyCourseTitleToHeader,
            setPlanningStreamVisible,
            hydrateDetailedPlanFromSnapshot,
            resumeSessionId,
            replayThread,
            emitLog,
            texts,
        });

        const resumed = await attemptResume(resumeSessionId, resumeFromSnapshot, elements, setResumeBootLoading);

        // What the user left open and where the user scrolled comes back after a reload, and is kept from
        // then on. It is not awaited: the page is already usable while it settles.
        restoreAndTrackUiState({
            root: document,
            win: window,
            storage: tabStorage(window),
            getSessionId: () => resumeSessionId || Number(state.sessionid || 0),
            restore: resumed,
        }).catch(() => undefined);

        contextUi.renderGuidelineList();
        stepsUi.updateFlowNav();
        contextUi.updateGenerateButton();

        // Initialize sidebar.
        initSidebar(state, actions.resetForAnotherCourse);

        // Initialize resizable splitter (§2.1).
        createSplitter({
            workspace: document.getElementById('courseaiWorkspace'),
            divider: document.getElementById('cgSplitter'),
        });

        // Wire collapsible checklist delegate listener (WU2).
        initChecklistCollapse();

        // Wire send-button ready-state toggle (WU3): accent-fills #btnCompactRegenerate
        // when the compact textarea has non-empty text.
        wireReadyToggle(elements);
    } catch (error) {
        Notification.exception(error);
    }
};
